const TONES={friendly:['😊 Friendly','happy',1.15,.95,''],bossy:['😠 Bossy','upset',.8,1.12,'t-bossy'],whiny:['😩 Whiny','sad',1.5,.75,'t-whiny'],sarcastic:['🙄 Sarcastic','think',1,.82,'t-sarc'],rude:['😤 Rude','upset',.85,1.05,'t-bossy']};
