function arcRow(unit){return `<div class="ag-row">${Object.entries(ARC_GAMES).map(([k,[ic,n]])=>`<button class="ag-pick" data-arc="${k}" type="button"><b>${ic}</b>${n}</button>`).join('')}</div>`;}
