  let order=L.two?[mk(),mk()]:[mk()];window.RikiG6.bk=()=>({order,sel});let cur=order.map(()=>({}));sel=0;let asked=false,changed=false,first=true;draw(cur,sel);$id('bkAsk').disabled=false;$id('bkServe').disabled=false;
