const G6CSS=`.g6-cast{display:flex;align-items:flex-end;gap:8px;margin-bottom:8px}.g6-av{width:62px;height:80px;flex:none}.g6-av svg,.g6-av img{width:100%;height:100%}.g6-bub{flex:1;position:relative;background:#fff;border-radius:18px;padding:8px 12px;box-shadow:0 0 0 2px #f3d6dc;min-height:54px}.g6-bub small{display:block;font-size:11px;font-weight:900;color:#b08aa0}.g6-bub span{font-weight:900;font-size:16px;color:#4a2338}.g6-bub.on{animation:zPop .3s}.g6-bub.g6-hid span{color:#b9a6c9;font-style:italic}
.g6-row{display:flex;gap:8px;margin-top:8px}.g6-row>*{flex:1}.g6-pips{display:flex;gap:5px;justify-content:center;margin-top:8px}.g6-pips i{width:12px;height:12px;border-radius:50%;background:#eee}.g6-pips i.on{background:#e2457a}
.esc-code{text-align:center;font-size:20px;font-weight:900;color:#4a2338;letter-spacing:4px;margin-bottom:6px}.esc-code b{display:inline-grid;place-items:center;width:30px;height:36px;border-radius:8px;background:#f3eef3;margin:0 2px;color:#b9a6c9}.esc-code b.on{background:#ffd34d;color:#4a2338}.esc-box{font-size:30px;animation:zPop .5s}
.esc-room{position:relative;display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:10px;border-radius:22px;background:linear-gradient(#fff6e3,#ffe9c9);box-shadow:inset 0 0 0 4px #f0d3a8}.esc-spot{border:0;border-radius:16px;padding:8px 2px;background:#fff;display:flex;flex-direction:column;align-items:center;box-shadow:0 4px 0 #e8c79a;cursor:pointer;font-weight:900;color:#4a2338}.esc-spot b{font-size:30px}.esc-spot small{font-size:11px}.esc-spot.ok{background:#d9f7e6;box-shadow:0 4px 0 #9fe0bd}
.esc-psst{position:absolute;top:40%;border:0;border-radius:999px;padding:8px 14px;background:#fff;box-shadow:0 4px 12px #0003;font-weight:900;color:#a2264f;animation:zPop .3s;z-index:3;cursor:pointer}
.bk-wrap{display:grid;gap:8px}.bk-tray{display:flex;justify-content:center;gap:12px;min-height:100px;padding:10px;border-radius:20px;background:linear-gradient(#fff,#ffeef4);box-shadow:inset 0 -6px 0 #ffd1e4}.bk-item{position:relative;width:90px;height:90px;display:grid;place-items:center;border-radius:18px;background:#fff;box-shadow:0 0 0 2px #f3d6dc;cursor:pointer}.bk-item.on{box-shadow:0 0 0 4px #e2457a}.bk-base{font-size:52px}.bk-ice{position:absolute;top:16px;left:22px;right:22px;height:20px;border-radius:50% 50% 30% 30%;box-shadow:inset 0 -3px 0 #0001}.bk-top{position:absolute;top:2px;font-size:24px}
.bk-pal{display:grid;gap:6px}.bk-pal>div{display:flex;align-items:center;gap:6px}.bk-pal small{width:74px;font-weight:900;color:#8a6577;font-size:12px}.bk-pal button{width:46px;height:46px;border:0;border-radius:14px;background:#fff;font-size:26px;box-shadow:0 3px 0 #e6d0dc,0 0 0 2px #f3d6dc;cursor:pointer}.g6-tips{margin-top:8px;text-align:center;font-weight:900;color:#4a2338}
.hm-list{display:grid;gap:4px;padding:8px 12px;border-radius:16px;background:#fff7d6;font-weight:900;font-size:14px;color:#4a2338}.hm-list .ok{color:#1f7a4c}
.hm-room{position:relative;display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:8px;padding:12px 12px 60px;border-radius:22px;background:linear-gradient(#ffe9f3 60%,#e7c19c 60%);min-height:250px}.hm-item{font-size:40px;text-align:center;touch-action:none;cursor:grab;filter:drop-shadow(0 4px 3px #0002);z-index:2}.hm-item.drag{z-index:5}.hm-spot{border-radius:16px;background:#fffc;display:flex;flex-direction:column;align-items:center;padding:6px;box-shadow:0 0 0 2px #fff,0 4px 8px #0001}.hm-spot b{font-size:30px}.hm-spot small{font-size:11px;font-weight:900;color:#6a4558}.hm-spot.ok{background:#d9f7e6}
.hm-tv{position:absolute;left:50%;bottom:8px;transform:translateX(-50%);border:0;border-radius:14px;padding:6px 14px;background:#3d3550;color:#fff;font-weight:900;font-size:18px;cursor:pointer}.hm-tv.on{background:linear-gradient(#8fd3ff,#ff9cc6);color:#2a1d2a;animation:zGlow .8s 2}.hm-tv.reward{animation:zPop .5s}
.cj-shelf{display:flex;justify-content:space-around;align-items:flex-end;padding:12px;border-radius:22px;background:linear-gradient(#fff3e6,#ffe0c4)}.cj-jar{font-size:60px;text-align:center;display:flex;flex-direction:column;align-items:center;transition:transform .4s}.cj-jar small,.cj-marbles small{font-size:12px;font-weight:900;color:#6a4558}.cj-jar.open{transform:scale(1.3) rotate(-8deg);animation:zGlow 1s 3}
.cj-marbles{display:flex;flex-direction:column;align-items:center}.cj-glass{width:90px;height:110px;border-radius:12px 12px 26px 26px;border:4px solid #cfe6f5;border-top-width:8px;background:#ffffff99;display:flex;flex-wrap:wrap-reverse;align-content:flex-start;gap:3px;padding:6px;box-sizing:border-box}.cj-glass i{width:18px;height:18px;border-radius:50%;box-shadow:inset -3px -3px 0 #0002,inset 2px 2px 0 #fff8;animation:zPop .4s}
.ft-pass{display:flex;justify-content:space-around;padding:8px;border-radius:16px;background:#eef6ff;font-size:28px}.ft-pass span{position:relative;opacity:.4}.ft-pass span.ok,.ft-pass span.meh{opacity:1}.ft-pass i{position:absolute;right:-10px;bottom:-6px;font-size:16px;font-style:normal}
.ft-stage{margin-top:8px}.ft-scene{position:relative;height:140px;border-radius:18px;background:linear-gradient(#bfe8ff,#e8f7ff);overflow:hidden}.ft-scene span{position:absolute;font-weight:900;background:#fff;border-radius:999px;padding:4px 10px;box-shadow:0 3px 8px #0002;animation:pdFloat 1.5s ease-out forwards}
.ft-museum{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:10px;border-radius:20px;background:#f4efe6}.ft-ex{border:0;border-radius:16px;padding:14px 0;font-size:40px;background:#fff;box-shadow:0 4px 0 #e0d6c4;cursor:pointer}.ft-ex.shine{animation:zGlow 1s infinite;box-shadow:0 0 0 4px #ffd34d}.ft-ex.no{background:#ffe1e6}.ft-ex.ok{background:#d9f7e6}.ft-shop{text-align:center;font-size:44px;padding:10px;border-radius:20px;background:#fff0f6}
.dc-floor{position:relative;height:170px;border-radius:22px;background:repeating-conic-gradient(#ffd1e4 0 25%,#e9dcff 0 50%) 0 0/40px 40px;display:grid;place-items:center;overflow:hidden}.dc-doll{width:96px;height:130px;transition:transform .2s}.dc-doll svg,.dc-doll img{width:100%;height:100%}.dc-doll.mv-spin{animation:dcSpin .45s}.dc-doll.mv-jump{transform:translateY(-26px)}.dc-doll.mv-clap{transform:scale(1.1)}.dc-doll.mv-wave{transform:rotate(-10deg)}@keyframes dcSpin{to{transform:rotateY(360deg)}}
.dc-light{position:absolute;top:10px;right:10px;width:34px;height:34px;border-radius:50%;background:#58c98a;box-shadow:0 0 12px #58c98a}.dc-light.red{background:#ff4d6d;box-shadow:0 0 24px #ff4d6d;animation:zGlow .5s 3}.dc-light.fake{background:#ffb547;box-shadow:0 0 14px #ffb547}
.dc-pad{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:8px}.dc-pad button{border:0;border-radius:18px;padding:10px 0;background:linear-gradient(#fff,#ffeef6);display:flex;flex-direction:column;align-items:center;font-weight:900;color:#4a2338;box-shadow:0 5px 0 #f0c1d6;cursor:pointer}.dc-pad b{font-size:30px}.dc-pad button:active{transform:translateY(3px)}`;
