const PROP_WORDS=[['crayon','crayon'],['cookie','cookie'],['cake','cake'],['snack','cookie'],['candy','candy'],['tablet','tablet'],['screen','tablet'],['game froze','tablet'],['tv','remote'],['remote','remote'],['show','remote'],['movie','remote'],['ball','ball'],['tower','block'],['block','block'],['lego','block'],['juice','juice'],['spill','juice'],['marker','marker'],['book','book'],['card','cards'],['drawing','drawing'],['paper','drawing'],['homework','drawing'],['picture','drawing'],['teddy','toy'],['toy','toy'],['doll','toy'],['jump rope','rope'],['pencil','pencil'],['eraser','pencil'],['backpack','backpack'],['puzzle','puzzle'],['lunch','tray'],['tray','tray'],['present','heart'],['swing','ball']];
function propFor(text){const s=' '+String(text).toLowerCase().replace(/[’']/g,'')+' ';for(const [w,k] of PROP_WORDS){const re=new RegExp('(^|[^a-z])'+w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(s|es)?([^a-z]|$)');if(re.test(s))return k;}return 'star';}
