function actionFor(text,good){const s=text.toLowerCase();for(const [a,re] of ACTIONS){if(re.test(s)){if(!good&&['share','give','wait','kind'].includes(a))continue;if(good&&['break','grab','throw','hide','push','shout','laugh'].includes(a)&&!/half|split/.test(s))continue;return a;}}return good?'kind':'shout';}
