function thSetup(sceneText){const L=thLayer();if(!L)return;const old=$id('slProp');if(old)old.style.display='none';const k=propFor(sceneText);L.innerHTML=`<div class="th-prop" id="thProp" style="${k==='star'?'opacity:0':''}">${clay(k)}</div>`;L.dataset.kind=k;}
